 19	static int append_bytes(char *buffer,
 20	                        size_t buffer_size,
 21	                        size_t *used,
 22	                        const char *text,
 23	                        size_t len)
 24	{
 25	    if (!buffer || !used || !text) {
 26	        return AGENT_ERROR_INVALID;
 27	    }
 28	    if (*used + len >= buffer_size) {
 29	        if (buffer_size > 0u) {
 30	            buffer[*used < buffer_size ? *used : buffer_size - 1u] = '\0';
 31	        }
 32	        return AGENT_ERROR_CONTEXT_OVERFLOW;
 33	    }
 34	
 35	    memcpy(buffer + *used, text, len);
 36	    *used += len;
 37	    buffer[*used] = '\0';
 38	    return AGENT_OK;
 39	}
