160	    ret = append_separator(buffer, buffer_size, used);
161	    if (ret != AGENT_OK) {
162	        *used = before;
163	        buffer[before] = '\0';
164	        return provider_is_critical(provider) ? ret : AGENT_OK;
165	    }
166	
167	    ret = provider->build(buffer + *used,
168	                          buffer_size - *used,
169	                          &written,
170	                          provider->user_data);
171	    if (ret != AGENT_OK) {
172	        *used = before;
173	        buffer[before] = '\0';
174	        return provider_is_critical(provider) ? ret : AGENT_OK;
175	    }
176	    if (*used + written >= buffer_size) {
177	        *used = before;
178	        buffer[before] = '\0';
179	        return provider_is_critical(provider) ? AGENT_ERROR_CONTEXT_OVERFLOW
180	                                              : AGENT_OK;
181	    }
182	
183	    *used += written;
184	    buffer[*used] = '\0';
185	    return AGENT_OK;
186	}
