622	 */
623	int agent_session_add_assistant_tool_calls(agent_t *agent,
624	                                           agent_session_t *session,
625	                                           const agent_tool_call_t *calls,
626	                                           size_t call_count)
627	{
628	    agent_session_entry_t *entry;
629	    size_t i;
630	    int err;
631	
632	    if (!agent || !session || !calls || call_count == 0u) {
633	        return AGENT_ERROR_INVALID;
634	    }
635	
636	    if (call_count > CAGENT_SESSION_MAX_TOOL_CALLS) {
637	        return AGENT_ERROR_LIMIT;
638	    }
639	
640	    if (!session_has_unfinished_turn(session)
641	        || session_has_pending_tool_calls(session)) {
642	        return AGENT_ERROR_INVALID;
643	    }
644	
645	    err = ensure_space(agent, session);
646	    if (err != AGENT_OK) {
647	        return err;
648	    }
649	
650	    entry = &session->entries[session->count];
651	    memset(entry, 0, sizeof(*entry));
652	
653	    entry->role = AGENT_MESSAGE_ROLE_ASSISTANT;
654	    entry->timestamp_ms = agent_runtime_now_ms(&agent->runtime);
655	    entry->turn_boundary = false;
656	    entry->tool_call_count = (uint32_t)call_count;
657	
658	    for (i = 0u; i < call_count; i++) {
659	        agent_session_tool_call_t *dst = &entry->tool_calls[i];
660	        err = copy_string(dst->id, sizeof(dst->id), calls[i].id, false, NULL);
661	        if (err != AGENT_OK) {
662	            memset(entry, 0, sizeof(*entry));
663	            return err;
664	        }
665	        err = copy_string(dst->name, sizeof(dst->name), calls[i].name, false, NULL);
666	        if (err != AGENT_OK) {
667	            memset(entry, 0, sizeof(*entry));
668	            return err;
669	        }
670	        err = copy_string(dst->arguments_json,
671	                          sizeof(dst->arguments_json),
672	                          calls[i].arguments_json ? calls[i].arguments_json : "{}",
673	                          false,
674	                          NULL);
675	        if (err != AGENT_OK) {
676	            memset(entry, 0, sizeof(*entry));
677	            return err;
678	        }
679	    }
680	
681	    session->count++;
682	    return AGENT_OK;
683	}
